	private static byte[] bitmapHeader(long bits) {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		bytes.write(HDTBitmap.BITMAP1);
		writeVByte(bytes, bits);
		byte[] header = bytes.toByteArray();
		CRC8 crc = new CRC8();
		crc.update(header, 0, header.length);
		bytes.write((int) crc.getValue());
		return bytes.toByteArray();
	}

	private static byte[] header(int declaredLength, byte[] data) {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		bytes.writeBytes(HDTPart.COOKIE);
		bytes.write(HDTPart.Type.HEADER.getValue());
		bytes.writeBytes(HDTHeader.HEADER_FORMAT);
		bytes.write(0);
		bytes.writeBytes(("length=" + declaredLength + ";").getBytes(StandardCharsets.US_ASCII));
		bytes.write(0);
		byte[] control = bytes.toByteArray();
		CRC16 crc = new CRC16();
		crc.update(control, 0, control.length);
		bytes.write((int) crc.getValue() & 0xff);
		bytes.write((int) (crc.getValue() >>> 8) & 0xff);
		bytes.writeBytes(data);
		return bytes.toByteArray();
	}

	private static byte[] log64ArrayHeader(int bitsPerEntry, long entries) {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		bytes.write(bitsPerEntry);
		writeVByte(bytes, entries);
		CRC8 crc = new CRC8();
		crc.update(HDTArray.Type.LOG64.getValue());
		byte[] metadata = bytes.toByteArray();
		crc.update(metadata, 0, metadata.length);
		bytes.write((int) crc.getValue());
		return bytes.toByteArray();
	}

	private static byte[] log64Array(int bitsPerEntry, long entries, byte[] data) {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		bytes.writeBytes(log64ArrayHeader(bitsPerEntry, entries));
		bytes.writeBytes(data);
		writeCRC32(bytes, data);
		return bytes.toByteArray();
	}

	private static byte[] vbytes(long... values) {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		for (long value : values) {
			writeVByte(bytes, value);
		}
		return bytes.toByteArray();
	}

	private static byte[] dictionary(int totalStrings, int declaredLength, int stringsBlock, byte[] data) {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		writeVByte(bytes, totalStrings);
		writeVByte(bytes, declaredLength);
		writeVByte(bytes, stringsBlock);
		CRC8 crc = new CRC8();
		crc.update(HDTDictionarySection.Type.FRONT.getValue());
		byte[] metadata = bytes.toByteArray();
		crc.update(metadata, 0, metadata.length);
		bytes.write((int) crc.getValue());
		bytes.write(HDTArray.Type.LOG64.getValue());
		bytes.writeBytes(log64Array(1, 1, new byte[] { 0 }));
		bytes.writeBytes(data);
		if (data.length == declaredLength) {
			writeCRC32(bytes, data);
		}
		return bytes.toByteArray();
	}

	private static void writeVByte(ByteArrayOutputStream bytes, long value) {
		while (value > 0x7f) {
			bytes.write((int) (value & 0x7f));
			value >>>= 7;
		}
		bytes.write((int) value | 0x80);
	}

	private static void writeCRC32(ByteArrayOutputStream bytes, byte[] data) {
		CRC32 crc = new CRC32();
		crc.update(data, 0, data.length);
		long checksum = crc.getValue();
		for (int i = 0; i < 4; i++) {
			bytes.write((int) (checksum >>> (i * 8)) & 0xff);
		}
	}

	private static InputStream oneByteBulkReads(byte[] data) {
		return new ByteArrayInputStream(data) {
			@Override
			public synchronized int read(byte[] bytes, int off, int len) {
				return super.read(bytes, off, Math.min(len, 1));
			}
		};
	}
